document.addEventListener('change',async e=>{const el=e.target,id=el.id;try{if(id==='compare-left'||id==='compare-right'){if(!compareSources.some(([key])=>key===el.value))return;S[id==='compare-left'?'compareLeft':'compareRight']=el.value;$('#image-results').innerHTML=imageResults();return}if(id==='scenario'){scenario(el.value);return}if(id==='mode'){S.mode=el.value;render();return}if(el.closest('#scan-config')){if(el.dataset.criterion){S.criteria=el.checked?[...S.criteria,el.dataset.criterion]:S.criteria.filter(x=>x!==el.dataset.criterion);$('#scan-results').innerHTML=scanResults()}dirtyScan();return}if(id==='map-compare'||id==='map-prediction'){S.compare=$('#map-compare').checked;S.prediction=$('#map-prediction').checked;rememberScan();render();return}if(id==='upload-input'){await uploadFile(el.files[0]);return}if(id==='image-fit'){if(S.run)return;S.imageFit=el.value;await convertSelected();dirtyImage();render();return}if(id==='image-ds'){S.imageDS=el.value;dirtyImage();return}if(id==='image-fault'){S.imageFault=el.value;dirtyImage();render();return}if(id==='image-seed'){S.imageSeed=el.value;dirtyImage();return}if(id==='image-count'){S.imageCount=el.value;dirtyImage();return}if(el.closest('#image-fault-fields')){S.imageFixed=S.imageFixed||{};S.imageFixed[id]=el.value;dirtyImage();return}if(id==='repair-method'){S.repair=el.value;render();return}if(id==='eval-source'){S.evalFull=el.value==='full';S.evalSource=el.value;S.evalReady=false;render();return}if(el.dataset.evalDs){S.evalDS=el.checked?[...S.evalDS,el.dataset.evalDs]:S.evalDS.filter(x=>x!==el.dataset.evalDs);S.evalReady=false;$('#eval-table').innerHTML=evaluationTable();return}if(id==='wave-candidate'){S.evalCandidate=el.value;$('#wave-area').innerHTML=waveform();return}if(id==='wave-samples'){S.waveSamples=el.checked;refreshWave();return}if(id==='wave-diff'){S.bitDiff=el.checked;$('#wave-area').innerHTML=waveform();return}if(el.dataset.sessionCheck){el.checked?S.selectedSessions.add(el.dataset.sessionCheck):S.selectedSessions.delete(el.dataset.sessionCheck);return}if(id==='session-status'||id==='session-task'||id==='session-date'){S.sessionFilter=$('#session-status').value;S.taskFilter=$('#session-task').value;S.sessionDate=$('#session-date').value;render();if($('#session-date'))$('#session-date').value=S.sessionDate||'';return}if(id==='report-source'){$('#report-preview').innerHTML=reportPreview();applyReportSections();return}if(el.dataset.reportSection!==undefined){applyReportSections();return}}catch(error){toast(error.message)}});
