window.addEventListener('hashchange',()=>{if($('#scan-config'))rememberScan();$('.sidebar').classList.remove('open');render();window.scrollTo(0,0)});
function flowContent(which){const flows={scan:{title:'一 / 容错边界扫描',steps:['能力范围与合法 d/s','参数与载荷','计划预览 / 非法点拒绝','独立计划封存','执行状态与安全停止','三判据热力图 / 格点证据'],note:'多组 d/s 分别建计划和会话。CONFIG、参照和正式扫描都计入额度；修改输入使旧计划失效。边界细化先显示建议与完整重复组预算；模型辅助入口未验收。'},images:{title:'二 / 图片传输与修复',steps:['本地上传 / 灰度转换','整图统一手选 d/s','PS 种子计划封存','CONFIG + 64 ITEM','五路图像 / 缺失区','修复详情与独立评价'],note:'没有逐块自动 d/s 调优。随机连续毛刺每块共享 bit/phase/width，count 0～255；计划毛刺数和实际误码数分开。算法是否用原图与评价是否用原图分别记录。'},evaluate:{title:'三 / B 参数评估与推荐',steps:['选择原始证据','核对 64 ITEM 覆盖','合法候选集合','软件推演 / 明确拒答','整图统一 d/s 区域','实测验证 → 独立复核'],note:'枚举不是 AI；局部 CAP 4096 点仅约 41 μs，不能当整帧。证据不足可没有推荐；不逐块取最优拼接。软件波形标注不代表重发或电气修复。'}};return notice('独立 UI 审批稿；不接硬件、不修改接口、不执行试验、不合入现有工作台。','warn')+Object.entries(flows).filter(([k])=>!which||k===which).map(([,f])=>`<h3>${f.title}</h3><div class="flow">${f.steps.map(x=>`<b>${x}</b>`).join(' → ')}</div><p>${f.note}</p>`).join('')+`<h3>全局工作方式</h3><p>顶部固定来源和 UI 演示水印；运行固定进度与停止。UNKNOWN 阻断继续，独占冲突不能抢占；无自动复位、清 FIFO 或烧录按钮。会话与报告保存历史故障。</p><h3>负责人审批范围</h3><p>导航 / 页面布局、任务步骤、参数分层、状态语义、证据详情和导出内容。批准界面设计不等于批准后端接口变更或实板执行。串口屏和 PL 传输加速仅预留扩展位置。</p>`}
function stateSpec(){return `<table><thead><tr><th>状态</th><th>允许的 UI 操作</th><th>不可推导的结论</th></tr></thead><tbody><tr><td>空白</td><td>编辑 / 选来源</td><td>无结果，不填成功率</td></tr><tr><td>就绪</td><td>预览 → 封存</td><td>不等于硬件验收</td></tr><tr><td>运行</td><td>只读详情 / 安全停止</td><td>不能改封存配置</td></tr><tr><td>正常完成</td><td>查看原件 / 导出</td><td>业务结果可能失败</td></tr><tr><td>混合 / 不足次数</td><td>独立统计 / 显示建议</td><td>1/1 不等于 3 次全成功</td></tr><tr><td>异常 / 锁冲突</td><td>查看占用及诊断</td><td>不能自动抢锁或复位</td></tr><tr><td>UNKNOWN</td><td>保留原件 / 阻断继续</td><td>不是失败标签，不能普通重试</td></tr><tr><td>未执行取消</td><td>保留取消索引</td><td>不算有效测量或物理 START</td></tr></tbody></table>`}
async function digest(bytes){if(!globalThis.crypto?.subtle)throw Error('当前浏览器上下文不支持 SHA256，请在本地预览地址中打开');const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}
const encoder=new TextEncoder();
function canvas(w=128,h=128){const c=document.createElement('canvas');c.width=w;c.height=h;return c}
async function demoImage(){if(S.run){toast('任务运行中，不能替换源图');return}const c=canvas(256,256),ctx=c.getContext('2d');ctx.fillStyle='#edf1f2';ctx.fillRect(0,0,256,256);ctx.fillStyle='#283d4a';ctx.fillRect(17,17,222,42);ctx.fillStyle='#fff';ctx.font='bold 23px sans-serif';ctx.fillText('TRI-BOARD LAB',28,45);for(let y=0;y<7;y++)for(let x=0;x<7;x++){ctx.fillStyle=(x+y)%2?'#d4dcdf':'#475f6b';ctx.fillRect(18+x*14,77+y*14,14,14)}ctx.strokeStyle='#344f5e';ctx.lineWidth=3;for(let r=16;r<52;r+=7){ctx.beginPath();ctx.arc(186,128,r,0,Math.PI*2);ctx.stroke()}const g=ctx.createLinearGradient(18,0,235,0);g.addColorStop(0,'black');g.addColorStop(1,'white');ctx.fillStyle=g;ctx.fillRect(18,192,220,22);ctx.fillStyle='#657984';ctx.font='12px monospace';ctx.fillText('128 x 128  /  GRAY8',23,236);await addImage(c.toDataURL(),'校准图_UI_DEMO.png',true)}
async function uploadFile(file){if(!file)return;if(S.run){toast('运行中不能替换图片');return}const error=$('#upload-error');if(error)error.textContent='';if(!/\.(png|jpe?g|webp|bmp)$/i.test(file.name)){if(error)error.textContent='请选择 PNG、JPEG、WebP 或 BMP 图片。';return}if(file.size>20*1024*1024){if(error)error.textContent='本地预览限 20 MB，请选较小图片。';return}const bytes=new Uint8Array(await file.slice(0,16).arrayBuffer());const valid=(bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71)||(bytes[0]===255&&bytes[1]===216)||(String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP')||(bytes[0]===66&&bytes[1]===77);if(!valid){if(error)error.textContent='文件内容不是受支持的图片，不能仅修改扩展名。';return}const url=URL.createObjectURL(file);try{await addImage(url,file.name,false)}catch(err){if($('#upload-error'))$('#upload-error').textContent=err.message;toast(err.message)}finally{URL.revokeObjectURL(url)}}
async function addImage(url,name,demo){const img=new Image();img.src=url;await new Promise((resolve,reject)=>{if(img.complete&&img.naturalWidth)return resolve();img.onload=resolve;img.onerror=()=>reject(Error('图片解码失败，请换一张受支持的图片'))});if(img.naturalWidth*img.naturalHeight>16000000)throw Error('图片尺寸超过本地预览上限 1600 万像素');const t=canvas(512,512),ctx=t.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,512,512);const scale=Math.min(512/img.naturalWidth,512/img.naturalHeight);ctx.drawImage(img,(512-img.naturalWidth*scale)/2,(512-img.naturalHeight*scale)/2,img.naturalWidth*scale,img.naturalHeight*scale);S.uploads.push({name,width:img.naturalWidth,height:img.naturalHeight,img,preview:t.toDataURL(),demo});S.selectedImage=S.uploads.length-1;await convertSelected();S.imageDirty=!!S.imagePlan;render();toast(demo?'已载入内置 UI 校准图':'已在本地转换，文件未上传至服务器')}
async function convertSelected(){const u=S.uploads[S.selectedImage];if(!u)return;const c=canvas(),ctx=c.getContext('2d',{willReadFrequently:true});ctx.fillStyle='white';ctx.fillRect(0,0,128,128);let scale=(S.imageFit==='contain'?Math.min:Math.max)(128/u.width,128/u.height);ctx.drawImage(u.img,(128-u.width*scale)/2,(128-u.height*scale)/2,u.width*scale,u.height*scale);const data=ctx.getImageData(0,0,128,128),gray=new Uint8Array(16384);for(let i=0;i<gray.length;i++){const p=i*4;gray[i]=Math.round(.299*data.data[p]+.587*data.data[p+1]+.114*data.data[p+2]);data.data[p]=data.data[p+1]=data.data[p+2]=gray[i];data.data[p+3]=255}ctx.putImageData(data,0,0);u.gray=gray;u.grayHash=await digest(gray);const generated={source:u.preview,gray:c.toDataURL()};for(const lane of ['a','b','stm','repair','diff']){const z=canvas(),k=z.getContext('2d');k.drawImage(c,0,0);if(lane==='a'||lane==='b'){for(let i=0;i<(lane==='a'?12:5);i++){const y=18+i*7; k.fillStyle=i%2?'#c7c7c7':'#282828';k.fillRect((i*23)%95,y,lane==='a'?28:12,1)}}if(lane==='stm'){k.fillStyle='#d5dce2';for(const y of [40,88]){k.fillRect(0,y,128,4);k.strokeStyle='#8496a7';for(let x=-10;x<140;x+=6){k.beginPath();k.moveTo(x,y);k.lineTo(x+4,y+4);k.stroke()}}}if(lane==='repair'){k.fillStyle='#999';k.fillRect(38,54,3,1)}if(lane==='diff'){k.fillStyle='#162c3c';k.fillRect(0,0,128,128);k.fillStyle='#e3b164';for(let i=0;i<8;i++)k.fillRect((i*23)%95,18+i*7,15,2)}k.fillStyle='#fff';k.fillRect(0,119,128,9);k.fillStyle='#536779';k.font='7px monospace';k.fillText('UI DEMO / NOT HARDWARE',3,126);generated[lane]=z.toDataURL()}S.images=generated}
function randomFromSeed(seed){let a=2166136261;for(const c of seed)a=Math.imul(a^c.charCodeAt(0),16777619);return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}}
async function sealImage(){if(S.run)throw Error('任务运行中，不能替换封存计划');const u=S.uploads[S.selectedImage];if(!u)throw Error('请先上传或载入图片');const rand=randomFromSeed($('#image-seed')?.value||S.imageSeed);let max=0,fixed=null;if(S.imageFault==='random'){S.imageSeed=$('#image-seed').value;max=integer($('#image-count').value,'每块最大 count',0,255);S.imageCount=String(max)}if(S.imageFault==='fixed'){fixed={byte:integer($('#image-byte').value,'起始 byte',20,275),count:integer($('#image-fixed-count').value,'数量',0,255),bit:integer($('#image-bit').value,'位号',0,7),phase:integer($('#image-phase').value,'相位',5,44),width:integer($('#image-width').value,'宽度',1,40)};if(fixed.byte+fixed.count>276||fixed.phase+fixed.width>45)throw Error('固定毛刺越过字节边界或相位 + 宽度大于 45')}const blocks=Array.from({length:64},(_,item)=>{if(fixed)return {item,...fixed};const count=S.imageFault==='disabled'?0:Math.floor(rand()*(max+1)),phase=5+Math.floor(rand()*20);return {item,byte:20+Math.floor(rand()*(256-Math.max(count,1)+1)),count,bit:Math.floor(rand()*8),phase,width:1+Math.floor(rand()*Math.min(12,45-phase))}});const p={origin:'UI_DEMO_ONLY',id:'UI-IMG-'+String(Date.now()).slice(-7),source_pixels_sha256:u.grayHash,fit:S.imageFit,ds:S.imageDS,seed:S.imageFault==='random'?S.imageSeed:null,mode:S.imageFault,blocks,totalRecords:65,totalPoints:blocks.reduce((n,b)=>n+b.count,0)};p.hash=await digest(encoder.encode(JSON.stringify(p)));S.imagePlan=p;S.imageDirty=false;render();toast('64 块演示计划已封存；未发送 CONFIG 或 ITEM')}
function exportData(){return {origin:'UI_DEMO_ONLY',real_experiment:false,hardware_connected:false,hardware_acceptance:false,source_view:S.mode,scenario:S.scenario,plan:S.plan,image_plan:S.imagePlan,example_sessions:fixtureSessions,raw_MMIO_transaction_binding_verified:null,records:[{id:18,status:'VALID_UI_FIXTURE',B_frame_correct:false,STM_payload_correct:true,STM_business_success:false},{id:12,status:'UNKNOWN',labels:null},{id:23,status:'CANCELLED_NOT_EXECUTED',physical_START:false}],notice:'All task records are UI fixtures, not hardware evidence.'}}
function mapSVG(){let cells='';for(let t=0;t<3;t++)for(let i=0;i<20;i++){let v=cellData(i,t),colors={pass:'#c5e5d7',fail:'#f0c7c4',mix:'#f4e4b9',short:'#fff8e7',unknown:'#e3d9ee',unmeasured:'#eef2f5',invalid:'#d6dfe7'},x=45+t*270+(i%4)*49,y=105+Math.floor(i/4)*36;cells+=`<rect x="${x}" y="${y}" width="45" height="31" fill="${colors[v.state]}" stroke="#b5c8d7"/><text x="${x+22}" y="${y+20}" text-anchor="middle" font-size="10">${v.label}</text>`}return `<svg xmlns="http://www.w3.org/2000/svg" width="850" height="340" viewBox="0 0 850 340"><rect width="850" height="340" fill="white"/><g font-family="sans-serif" fill="#28485d"><text x="30" y="30" font-size="16">UI_DEMO_ONLY · 三判据热力图 · 非硬件测量</text><text x="30" y="53" font-size="11">B d3/s−1 · byte24 bit2 · count1 · 目标重复3次 · 成功/有效</text>${heatLabels.map((x,t)=>`<text x="${45+t*270}" y="80" font-size="13">${x}</text>${[3,6,12,20].map((w,c)=>`<text x="${67+t*270+c*49}" y="98" font-size="10" text-anchor="middle">${w}</text>`).join('')}${[7,12,18,24,34].map((p,r)=>`<text x="${30+t*270}" y="${126+r*36}" font-size="10">${p}</text>`).join('')}`).join('')}${cells}<text x="30" y="308" font-size="11">横轴：宽度 w　纵轴：相位 φ　灰：未测　×：非法　?：UNKNOWN　*：不足目标次数</text><text x="30" y="328" font-size="11">离散格点，无插值；三个判据独立，不代表实板验收。</text></g></svg>`}
function download(name,content,type){const b=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已生成本地下载：'+name)}
async function blobFromData(uri){const [meta,data]=uri.split(',');const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));return new Blob([bytes],{type:meta.match(/data:(.*?);/)[1]})}
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^(0xedb88320&-(c&1))}return (c^0xffffffff)>>>0}
function zipStore(files){let offset=0;const local=[],central=[];const set16=(v,o,n)=>v.setUint16(o,n,true),set32=(v,o,n)=>v.setUint32(o,n,true);for(const [name,text] of Object.entries(files)){const filename=encoder.encode(name),body=encoder.encode(text),crc=crc32(body),header=new Uint8Array(30+filename.length),v=new DataView(header.buffer);set32(v,0,0x04034b50);set16(v,4,20);set16(v,6,0x0800);set32(v,14,crc);set32(v,18,body.length);set32(v,22,body.length);set16(v,26,filename.length);header.set(filename,30);local.push(header,body);const dir=new Uint8Array(46+filename.length),d=new DataView(dir.buffer);set32(d,0,0x02014b50);set16(d,4,20);set16(d,6,20);set16(d,8,0x0800);set32(d,16,crc);set32(d,20,body.length);set32(d,24,body.length);set16(d,28,filename.length);set32(d,42,offset);dir.set(filename,46);central.push(dir);offset+=header.length+body.length}const size=central.reduce((n,b)=>n+b.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);set32(ev,0,0x06054b50);set16(ev,8,central.length);set16(ev,10,central.length);set32(ev,12,size);set32(ev,16,offset);const output=new Uint8Array(offset+size+22);let p=0;for(const part of [...local,...central,end]){output.set(part,p);p+=part.length}return output}
render();
